  let dx = f32(cx - ox);
  let dy = f32(cy - oy);
  let glideAlt = originAlt + sqrt(dx * dx + dy * dy) * params.cellSizeM / params.glideRatio;
  return elev[idx(cx, cy)] >= glideAlt;
